# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Extra backend route for delulu-smash. POST /complete returns Python
#          completions for a cell, called straight from the editor so typing
#          doesn't go through Reflex state. POST /inline_edit: Alt+I inline chat
#          (inline_edit.py). POST /mention_complete: what can follow the dot in an "@" mention
#          (mentions.py). GET /char_icons/<file>.png serves the character stock icons
#          (ds.data.CHAR_ICON_DIR) for views that show them (render.ICON_URL).
#          GET /frameable: whether a clicked link's site lets our frame show it
#          (web.frameable; assets/panes.js). EXPERIMENT: GET /terminal + /terminal/ws, the
#          Terminal widget's page and the shell it runs (terminal.py).
# Usage: mounted by ui.py via rx.App(api_transformer=api).
# ---------------------------------------------------------------------------
from __future__ import annotations

import asyncio
from typing import TYPE_CHECKING

from ds.data import CHAR_ICON_DIR
from starlette.applications import Starlette
from starlette.middleware import Middleware
from starlette.middleware.cors import CORSMiddleware
from starlette.responses import JSONResponse
from starlette.routing import Mount, Route, WebSocketRoute
from starlette.staticfiles import StaticFiles

from ui import mentions, terminal
from ui.inline_edit import edit
from ui.session import complete as complete_code
from ui.session import find_session
from ui.web import frameable as frameable_check

if TYPE_CHECKING:
    from starlette.requests import Request


async def complete(request: Request) -> JSONResponse:
    body = await request.json()
    # jedi can take a moment on first use of a big module; keep it off the event loop
    items = await asyncio.to_thread(
        complete_code,
        str(body.get("token", "")),
        str(body.get("code", "")),
        int(body.get("line", 1)),
        int(body.get("column", 0)),
    )
    return JSONResponse(items)


async def inline_edit(request: Request) -> JSONResponse:
    return JSONResponse(await edit(await request.json()))


async def mention_complete(request: Request) -> JSONResponse:
    """What can follow the dot in an "@" mention being typed (mentions.complete), asked by
    assets/mentions.js on each keystroke after a dot, as the cell editor asks /complete.
    """
    body = await request.json()
    session = find_session(str(body.get("token", "")))
    # off the event loop: it reads a value's attributes, which can take a moment
    return JSONResponse(await asyncio.to_thread(mentions.complete, session, str(body.get("text", ""))))


async def frameable(request: Request) -> JSONResponse:
    """Whether a link can open as a glance (web.frameable): {"frameable": true | false | null,
    "why": ...}. assets/panes.js opens a refused one in a real browser tab instead.
    """
    ok, why = await frameable_check(request.query_params.get("url", ""))
    return JSONResponse({"frameable": ok, "why": why})


# The frontend (port 3000) calls the backend (port 8000), so the browser needs CORS headers.
api = Starlette(
    routes=[
        Route("/complete", complete, methods=["POST"]),
        Route("/inline_edit", inline_edit, methods=["POST"]),
        Route("/mention_complete", mention_complete, methods=["POST"]),
        Route("/frameable", frameable, methods=["GET"]),
        # EXPERIMENT: the Terminal widget's page and its shell (terminal.py; this machine only)
        Route("/terminal", terminal.page, methods=["GET"]),
        WebSocketRoute("/terminal/ws", terminal.shell_socket),
        # the folder's name is the url prefix, so ds.data.char_icon's value is the path
        Mount(f"/{CHAR_ICON_DIR.name}", StaticFiles(directory=CHAR_ICON_DIR), name="char_icons"),
    ],
    middleware=[Middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["GET", "POST"], allow_headers=["*"])],
)
